//! Submitter formNoValidate button metadata preserves trusted native editing and submission data.
use super::*;
struct Fixture(std::path::PathBuf);impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
fn click(app:&mut App,node:usize){let r=app.page.controls.iter().find(|r|r.node==node).unwrap();let(x,y)=(r.x+r.width/2,app.content_top()+r.y+r.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);}
fn post(app:&App,owner:usize)->String{let s=app.forms.submit_request(&app.document,owner,Some(node(app,"submit")),&app.location,&app.base_location).unwrap();let crate::http::Request::FormPost{body,..}=s.request else{panic!("POST")};String::from_utf8(body).unwrap()}
#[test]
fn submitter_form_no_validate_button_actual_app_trusted_typing_mode_changes_serialization_paint_and_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-submitter-form-no-validate-button-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}button{position:absolute;top:20px;width:130px;height:32px}#submit{left:20px;top:230px}#hard{left:20px}#soft{left:170px}#check{left:320px}#area{position:absolute;left:20px;top:80px;width:180px;height:70px}#neighbor{position:absolute;left:220px;top:100px;width:160px;height:30px}#stable{position:absolute;left:420px;top:100px}#paint{position:absolute;left:420px;top:160px;width:40px;height:30px;background:#114455}#paint.done{background:#cc2244}</style><form id=form method=post action=https://submitter-form-no-validate-button.test/submit><input id=area name=q autocomplete=off><input type=hidden name=_charset_ value=author><button id=submit type=submit name=go value=sent>Send</button></form><input id=neighbor value=neighbor><button id=hard>Hard</button><button id=soft>Soft</button><button id=check>Check</button><a id=stable href=#destination>Go</a><div id=paint></div><div id=destination></div><script>var x=document.getElementById('area'),z=document.getElementById('submit'),events=0;x.oninput=function(e){if(!e.isTrusted)throw 'untrusted input';events++;};document.getElementById('hard').onclick=function(e){if(!e.isTrusted||events!==4||x.value!=='A😀ZQ')throw 'trusted initial text';z.formNoValidate=true;if(z.formNoValidate!==true||x.value!=='A😀ZQ'||x.defaultValue!=='')throw 'hard metadata changed API';};document.getElementById('soft').onclick=function(e){if(!e.isTrusted||events!==4||x.value!=='A😀ZQ')throw 'hard changed API';z.formNoValidate=false;};document.getElementById('check').onclick=function(e){if(!e.isTrusted||events!==4||x.value!=='A😀ZQ'||z.formNoValidate!==false||x.defaultValue!=='')throw 'wrap must preserve native API';document.getElementById('paint').className='done';document.title='Submitter formNoValidate button checked';};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);let area=node(&app,"area");let owner=node(&app,"form");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");let buttons=["hard","soft","check"].map(|id|node(&app,id));let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let r=app.page.controls.iter().find(|r|r.node==area).unwrap();let rect=(r.x,r.y,r.width,r.height);let initial=app.draw();click(&mut app,area);for ch in ['A','😀','Z','Q']{app.text_input(ch);}assert_eq!(app.forms.controls[&area].value.text(),"A😀ZQ");let e=&app.forms.controls[&area].value;let selection=(e.cursor,e.anchor,e.offset);assert_eq!(post(&app,owner),"q=A%F0%9F%98%80ZQ&_charset_=UTF-8&go=sent");click(&mut app,buttons[0]);assert_eq!(post(&app,owner),"q=A%F0%9F%98%80ZQ&_charset_=UTF-8&go=sent");let e=&app.forms.controls[&area].value;assert_eq!((e.cursor,e.anchor,e.offset),selection);assert!(app.forms.controls[&area].dirty_value);click(&mut app,buttons[1]);assert_eq!(post(&app,owner),"q=A%F0%9F%98%80ZQ&_charset_=UTF-8&go=sent");
 app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}click(&mut app,buttons[2]);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,"Submitter formNoValidate button checked");let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+170)as usize*painted.width+430],0xcc2244);let r=app.page.controls.iter().find(|r|r.node==area).unwrap();assert_eq!((r.x,r.y,r.width,r.height),rect);let(left,top,right,bottom)=(r.x.max(0)as usize,(app.content_top()+r.y-app.scroll).max(0)as usize,(r.x+r.width).min(painted.width as i32)as usize,(app.content_top()+r.y-app.scroll+r.height).min(painted.height as i32)as usize);assert!(left<right&&top<bottom);assert!((top..bottom).any(|y|initial.pixels[y*initial.width+left..y*initial.width+right]!=painted.pixels[y*painted.width+left..y*painted.width+right]),"actual editor paint changes");let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!((app.raw.clone(),app.location.clone(),app.script_epoch),(raw,location,epoch));
}
